const docs = (function(){ try { return $('Leer comprobantes').all().map(i => i.json).filter(x => x && Object.keys(x).length); } catch(e) { return []; } })()
  .filter(d => d.CLASIFICACION === 'COMPROBANTE_EGRESO' && ['PROCESADO','SIN_MATCH','REVISAR'].includes(d.ESTADO));
const pagos = (function(){ try { return $('Leer TRANSPORTES_PAGOS').all().map(i => i.json).filter(x => x && Object.keys(x).length); } catch(e) { return []; } })();
const sols = (function(){ try { return $('Leer TRANSPORTES_SOLICITUDES').all().map(i => i.json).filter(x => x && Object.keys(x).length); } catch(e) { return []; } })();
const movs = (function(){ try { return $('Leer BANCOS_MOV').all().map(i => i.json).filter(x => x && Object.keys(x).length); } catch(e) { return []; } })();
const parseF = v => { if (!v) return null; if (v instanceof Date) return v;
  if (typeof v === 'number' && v > 20000 && v < 80000) return new Date(Date.UTC(1899,11,30) + Math.round(v)*86400000);
  const s = String(v).trim();
  if (/^\d+$/.test(s)) { const n = parseInt(s); if (n > 20000 && n < 80000) return new Date(Date.UTC(1899,11,30) + n*86400000); }
  let m = s.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{4})/);
  if (m) return new Date(m[3] + '-' + m[2].padStart(2,'0') + '-' + m[1].padStart(2,'0'));
  const d2 = new Date(s.replace(' ', 'T')); return isNaN(d2) ? null : d2; };
const norm = s => String(s || '').toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^A-Z0-9 ]/g,'');
const out = [];
for (const d of docs) {
  const val = parseFloat(d.OCR_VALOR);
  if (!val) { out.push({ json: { accion: 'ERROR', doc: d, motivo: 'OCR sin valor' } }); continue; }
  const pend = pagos.filter(p => p.ESTADO === 'PENDIENTE');
  // Score: valor (obligatorio ±1) + nombre transportista + teléfono en referencia OCR
  const neto = p2 => { const v = parseFloat(p2.PAGO_NETO); return isNaN(v) || !v ? parseFloat(p2.VALOR) : v; };
  // El comprobante muestra el NETO pagado (bruto - retefuente 1%); cruzar contra neto o bruto
  let candidatos = pend.filter(p => Math.abs(neto(p) - val) <= 1 || Math.abs(parseFloat(p.VALOR) - val) <= 1);
  let esAbono = false;
  if (candidatos.length === 0) {
    // Abono parcial: valor menor al pendiente, desempatar por nombre/teléfono
    candidatos = pend.filter(p => val < neto(p));
    esAbono = true;
  }
  if (candidatos.length > 1) {
    const ref = norm(d.OCR_REFERENCIA + ' ' + d.OCR_CLIENTE);
    const byPhone = candidatos.filter(p => {
      const sol = sols.find(s => s.ID_SOLICITUD === p.ID_SOLICITUD) || {};
      return sol.TELEFONO && ref.includes(String(sol.TELEFONO));
    });
    if (byPhone.length >= 1) candidatos = byPhone;
    else {
      const byName = candidatos.filter(p => norm(p.TRANSPORTISTA).split(' ').filter(w => w.length > 3).some(w => ref.includes(w)));
      if (byName.length >= 1) candidatos = byName;
    }
  }
  if (candidatos.length !== 1) {
      if (candidatos.length === 0 && d.ESTADO === 'SIN_MATCH') continue; // reintento silencioso
      if (candidatos.length > 1 && d.ESTADO === 'AMBIGUO') continue; // ya alertado, espera revisión humana
      out.push({ json: { accion: candidatos.length === 0 ? 'SIN_MATCH_TRANSPORTE' : 'AMBIGUO', doc: d, motivo: candidatos.length + ' candidatos en TRANSPORTES_PAGOS' } }); continue;
    }
  const p = candidatos[0];
  // Anti-duplicado nivel comprobante: ¿ya hay un pago PAGADO con este ID_DOC_WA o mismo valor+transportista+fecha?
  const yaPagado = pagos.find(x => x.ESTADO === 'PAGADO' && (x.ID_DOC_WA === d.ID_DOC || (Math.abs(parseFloat(x.VALOR)-val)<=1 && norm(x.TRANSPORTISTA)===norm(p.TRANSPORTISTA) && x.FECHA_PAGO === d.OCR_FECHA_PAGO)));
  if (yaPagado) {
    out.push({ json: { accion: 'DUPLICADO', doc: d, pago: p, motivo: 'Ya existe pago ' + yaPagado.ID_PAGO + ' con mismo valor/transportista/fecha' } });
    continue;
  }
  // Anti-duplicado nivel banco: ¿existe ya el egreso real en el extracto?
  const movReal = movs.find(m => { if (m.ID_CONCILIACION) return false; const mv = parseFloat(m.VALOR); if (!(mv <= -val + 1 && mv >= -val - 1) || m.TIPO !== 'EGRESO') return false; const fd = parseF(d.OCR_FECHA_PAGO), fm2 = parseF(m.FECHA); if (fd && fm2) return Math.abs((fm2 - fd) / 86400000) <= 3; return true; });
  const sol = sols.find(s => s.ID_SOLICITUD === p.ID_SOLICITUD) || {};
  out.push({ json: { accion: 'MATCH', doc: d, pago: p, sol, esAbono, valorPagado: val, movRealExistente: movReal ? movReal.ID_MOV : '' } });
}
return out;

// Si fue ABONO, crear nueva fila PENDIENTE por el saldo y actualizar estado de la solicitud
const j = $('¿Resultado?').item.json;
const items = [];
const saldo = parseFloat(j.pago.VALOR) - j.valorPagado;
if (j.esAbono && saldo > 1) {
  items.push({ json: { crearSaldo: true, fila: {
    ID_PAGO: 'TRP-' + Date.now().toString().slice(-9),
    ID_SOLICITUD: j.pago.ID_SOLICITUD,
    ID_COMPRA: j.pago.ID_COMPRA,
    TRANSPORTISTA: j.pago.TRANSPORTISTA,
    CEDULA: j.pago.CEDULA,
    TIPO: 'SALDO',
    VALOR: saldo,
    MEDIO_PAGO: j.pago.MEDIO_PAGO,
    ESTADO: 'PENDIENTE',
    NOTAS: 'Saldo tras abono ' + j.pago.ID_PAGO
  }, estadoSolicitud: 'PARCIAL', j }});
} else {
  items.push({ json: { crearSaldo: false, estadoSolicitud: 'PAGADO', j }});
}
return items;

// Registrar el egreso en BANCOS_MOV evitando duplicados:
// si el egreso real ya está en el extracto, solo lo vinculamos; si no, creamos fila proyectada.
const d = $('Gestionar abono / saldo').item.json.j;
if (d.movRealExistente) {
  return [{ json: { modo: 'VINCULAR', ID_MOV: d.movRealExistente, idPago: d.pago.ID_PAGO } }];
}
return [{ json: { modo: 'CREAR', fila: {
  ID_MOV: 'MOV-' + Date.now().toString().slice(-9),
  FECHA: d.doc.OCR_FECHA_PAGO,
  CUENTA: d.pago.CUENTA_ORIGEN || 'BC-CTE-3762',
  DESCRIPCION: 'Pago transportista ' + d.pago.TRANSPORTISTA,
  REFERENCIA: d.pago.ID_PAGO,
  MONEDA: 'COP',
  VALOR: -Math.abs(d.valorPagado), // = neto real que salió del banco según el comprobante
  TIPO: 'EGRESO',
  CATEGORIA: 'TRANSPORTE',
  DETALLE: 'Cta cobro ' + (d.sol.CUENTA_COBRO || '') + ' Rem ' + (d.sol.REMISION || '') + ' via ' + d.pago.MEDIO_PAGO,
  FACTURA_OC: d.pago.ID_COMPRA,
  TERCERO: d.pago.TRANSPORTISTA + ' CC ' + d.pago.CEDULA,
  ID_CONCILIACION: d.pago.ID_PAGO,
  ESTADO_CONTABLE: 'PENDIENTE',
  ORIGEN: 'TRANSPORTE_APP'
}, idPago: d.pago.ID_PAGO }}];

parameters.query:
insert into bancos_mov (
  id_mov, fecha, cuenta, descripcion, referencia, moneda, valor, tipo, categoria, detalle,
  factura_oc, tercero, id_conciliacion, estado_contable, origen, human_review
) values (
  $1::text, $2::text::date, $3::text, $4::text, $5::text, 'COP', $6::text::numeric, 'EGRESO',
  'TRANSPORTE', $7::text, nullif($8::text,''), $9::text, $10::text, 'PENDIENTE', 'TRANSPORTE_APP', 'PENDIENTE'
)
on conflict (id_mov) do nothing;

update comprobantes_wa set id_mov_match = $2::text, estado = 'CONCILIADO_TRANSPORTE',
  human_review = 'PENDIENTE', updated_at = now()
where id_doc = $1::text;

